const b = $input.first().json.body || $input.first().json;
if (!b.user_id || !b.category_id || !b.fecha_ingreso) throw new Error('Faltan campos requeridos: user_id, category_id, fecha_ingreso');
return [{ json: {
  user_id: b.user_id,
  category_id: b.category_id,
  fecha_ingreso: b.fecha_ingreso,
  clinic_id: b.clinic_id ? String(b.clinic_id) : ''
} }];

const link = $('Parse Link User').first().json;
const user = $input.first().json;
if (!user || !user.id) throw new Error('Usuario no encontrado');

// Split name: first word = nombres, rest = apellidos
const nameParts = (user.name || '').trim().split(/\s+/);
const nombres = nameParts.length > 1 ? nameParts.slice(0, -1).join(' ') : user.name || '';
const apellidos = nameParts.length > 1 ? nameParts[nameParts.length - 1] : '';

return [{ json: {
  user_id: user.id,
  clinic_id: link.clinic_id || '',
  category_id: link.category_id,
  fecha_ingreso: link.fecha_ingreso,
  nombres,
  apellidos,
  email: user.email || '',
  telefono: user.phone_number || '',
  cedula: user.identity_document || '',
  fecha_nacimiento: user.birth_date || '',
  domicilio: user.address || '',
  cuenta_banco: user.bank_account || '',
  foto_url: user.avatar || ''
} }];

const employee = $input.first().json;
const link = $('Parse Link User').first().json;
return [{ json: {
  employee_id: employee.id,
  clinic_id: employee.clinic_id || link.clinic_id || '',
  category_id: link.category_id,
  fecha_inicio: link.fecha_ingreso,
  employee: employee
} }];

const employment = $input.first().json;
const employee = $('Prepare Employment Data').first().json.employee;
return [{ json: { ...employee, employment_id: employment.id } }];

